1: import 'package:mad_flutter_practicum/app/app.dart';
2: import 'package:mad_flutter_practicum/domain/domain.dart';
3: 
4: import 'widgets/widgets.dart';
5: 
6: class CurrencyListPage extends StatefulWidget {
7:   const CurrencyListPage({super.key});
8: 
9:   @override
10:   State<CurrencyListPage> createState() => _CurrencyListPageState();
11: }
12: 
13: class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
14:   late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
15: 
16:   late final AnimationController _fadeController;
17: 
18:   late Future<List<CurrencyModel>> _currencyListFuture;
19: 
20:   int _currentPage = 0;
21:   bool _isLoadingMore = false;
22:   bool _hasMore = true;
23: 
24:   List<CurrencyModel> _allCurrencies = [];
25: 
26:   @override
27:   void initState() {
28:     super.initState();
29:     _initAnimation();
30:     _initData();
31:   }
32: 
33:   @override
34:   void dispose() {
35:     _filteredCurrenciesNotifier.dispose();
36:     _fadeController.dispose();
37:     super.dispose();
38:   }
39: 
40:   void _initAnimation() {
41:     _fadeController = AnimationController(
42:       duration: Duration(milliseconds: 400),
43:       vsync: this,
44:     );
45:   }
46: 
47:   void _initData() {
48:     final currencyRepository = context.read<CurrencyRepository>();
49: 
50:     _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest()).then((CurrencyPage page) {
51:       final List<CurrencyModel> value = page.items;
52:       _allCurrencies = List.from(value);
53:       _filteredCurrenciesNotifier = ValueNotifier(value);
54: 
55:       _fadeController.forward(); // запускаем анимацию
56: 
57:       currencyRepository.saveCurrencyList(_allCurrencies);
58:       _hasMore = page.hasMore;
59: 
60:       return value;
61:     });
62:   }
63: 
64:   Future<void> _onLoadMore() async {
65:     if (_isLoadingMore || !_hasMore) return;
66: 
67:     setState(() {
68:       _isLoadingMore = true;
69:     });
70: 
71:     final currencyRepository = context.read<CurrencyRepository>();
72:     _currentPage++;
73: 
74:     try {
75:       final page = await currencyRepository.fetchRates(CurrencyPageRequest(page: _currentPage));
76: 
77:       if (mounted) {
78:         setState(() {
79:           _allCurrencies.addAll(page.items);
80:           _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
81:           _hasMore = page.hasMore;
82:           _isLoadingMore = false;
83:         });
84:       }
85:     } catch (_) {
86:       if (mounted) {
87:         setState(() {
88:           _isLoadingMore = false;
89:         });
90:       }
91:     }
92:   }
93: 
94:   void _filterCurrencies(String query) {
95:     final String lowerQuery = query.toLowerCase();
96:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
97:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
98:     });
99: 
100:     _filteredCurrenciesNotifier.value = result.toList(growable: false);
101:   }
102: 
103:   @override
104:   Widget build(BuildContext context) {
105:     return Scaffold(
106:       appBar: AppBar(title: Text(context.loc.currencyRate)),
107:       body: FutureBuilder(
108:         future: _currencyListFuture,
109:         builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
110:           final List<CurrencyModel>? data = snapshot.data;
111:           if (data == null) return const SizedBox.shrink();
112: 
113:           return FadeTransition(
114:             opacity: _fadeController.view,
115:             child: Column(
116:               children: [
117:                 Padding(
118:                   padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
119:                   child: SearchView(onChanged: _filterCurrencies),
120:                 ),
121:                 Expanded(
122:                   child: ValueListenableBuilder<List<CurrencyModel>>(
123:                     valueListenable: _filteredCurrenciesNotifier,
124:                     builder: (BuildContext context, List<CurrencyModel> data, _) {
125:                       return ListView.builder(
126:                         itemCount: data.length,
127:                         itemBuilder: (BuildContext context, int index) {
128:                           final CurrencyModel currency = data[index];
129: 
130:                           return Padding(
131:                             key: ValueKey(currency.id),
132:                             padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
133:                             child: CurrencyCard(model: currency),
134:                           );
135:                         },
136:                         padding: const EdgeInsets.fromLTRB(22, 0, 22, _hasMore ? 40 : 16),
137:                       );
138:                     },
139:                   ),
140:                 ),
141:                 if (_hasMore && !_isLoadingMore)
142:                   Padding(
143:                     padding: const EdgeInsets.all(16.0),
144:                     child: ElevatedButton(onPressed: _onLoadMore, child: Text(context.loc.showMore)),
145:                   )
146:                 else if (_isLoadingMore)
147:                   const Padding(
148:                     padding: EdgeInsets.all(16.0),
149:                     child: CircularProgressIndicator(),
150:                   ),
151:               ],
152:             ),
153:           );
154:         },
155:       ),
156:     );
157:   }
158: }

